using System.Reflection;
using Microsoft.AspNetCore.Hosting;
using Moq;
using WcgWeb.Models;
using WcgWeb.Services;
namespace WcgTests;

public sealed class EnergyKeywordTests
{
    readonly CardDatabase cards;
    public EnergyKeywordTests(){var env=new Mock<IWebHostEnvironment>();env.Setup(x=>x.ContentRootPath).Returns(Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../WcgWeb")));cards=CounterHistory.BeforeRulesSimplification(new(env.Object)); /* Pre-simplification rules, still used to replay saved ranked matches. */}
    GameEngine Scene(int energy=4){var g=new GameEngine(cards,new Random(17));g.StartGame(cards.PresetDecks[0],cards.PresetDecks[1]);foreach(var p in new[]{g.Player,g.Computer}){p.Hand.Clear();p.EnergyZone.Clear();for(int i=0;i<energy;i++)p.EnergyZone.Add(new(cards.GetCard("WCG-101")!));}g.Computer.IsAi=false;return g;}
    MonsterInstance Unit(PlayerState p,string id,int? power=null){var m=new MonsterInstance(cards.GetCard(id)!){Slot=p.Field.Count,IsTapped=false,HasSummoningSickness=false};if(power!=null)m.CurrentPP=power.Value;p.Field.Add(m);return m;}
    static void Choose(GameEngine g,string id)=>Assert.True(g.SelectChoice(g.CurrentPendingChoice!.Options.Single(o=>o.Id==id)));
    static void Invoke(GameEngine g,string name,params object[] args){typeof(GameEngine).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(g,args);typeof(GameEngine).GetMethod("Drain",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(g,null);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(4)]
    public void RageSpendsExactAmountAndBoostExpires(int n){var g=Scene();var a=Unit(g.Player,"WCG-201");Assert.True(g.Attack(g.Player,a));Assert.Equal(7,g.Computer.Hp);Choose(g,"RAGE:"+n);Assert.Equal(6-n,g.Computer.Hp);Assert.Equal(4-n,g.Player.AvailableEnergy);Assert.Equal(1,a.CurrentDP);Assert.True(a.IsTapped);Assert.False(g.IsWaiting);}
    [Fact] public void RagePrecedesGuardAndRemainingDamageCounter(){var g=Scene();var a=Unit(g.Player,"WCG-201");Unit(g.Computer,"WCG-200");Assert.True(g.Attack(g.Player,a));Choose(g,"RAGE:3");Assert.Equal(4,a.CurrentDP);Assert.Equal("computer",g.DecisionPlayerId);Choose(g,"GUARD:2");Assert.Equal(5,g.Computer.Hp);Assert.Equal(2,g.Computer.AvailableEnergy);Assert.Equal(1,a.CurrentDP);}
    [Fact] public void RageDoesNotTriggerOnMonsterOrSilencedSource(){foreach(var face in new[]{false,true}){var g=Scene();var a=Unit(g.Player,"WCG-201");if(face)a.IsSilenced=true;var d=face?null:Unit(g.Computer,"WCG-101");Assert.True(g.Attack(g.Player,a,d));Assert.False(g.IsWaiting);Assert.Equal(4,g.Player.AvailableEnergy);}}
    [Fact] public void RageStillRespectsTaunt(){var g=Scene();var a=Unit(g.Player,"WCG-201");Unit(g.Computer,"WCG-069");Assert.False(g.Attack(g.Player,a));Assert.Equal(4,g.Player.AvailableEnergy);}
    [Fact] public void LethalRageCleansTemporaryDamageEvenWhenEffectQueueStops(){var g=Scene(6);var a=Unit(g.Player,"WCG-201");Assert.True(g.Attack(g.Player,a));Choose(g,"RAGE:6");Assert.True(g.IsOver);Assert.Equal(1,a.CurrentDP);Assert.Equal(0,a.AttackDamageBonus);}
    [Fact] public void RageCounterDestroyingSourceKeepsPaymentAndDoesNotRetainBonus(){var g=Scene(5);var a=Unit(g.Player,"WCG-201");var c=new CardInstance(cards.GetCard("WCG-195")!);g.Computer.Hand.Add(c);Assert.True(g.Attack(g.Player,a));Choose(g,"RAGE:2");Choose(g,c.InstanceId.ToString());Assert.DoesNotContain(a,g.Player.Field);Assert.Equal(3,g.Player.AvailableEnergy);Assert.Equal(0,a.AttackDamageBonus);}
    [Fact] public void BothWildSourcesChooseOnceInAttackerThenDefenderOrder(){var g=Scene();var a=Unit(g.Player,"WCG-203");var d=Unit(g.Computer,"WCG-203");Assert.True(g.Attack(g.Player,a,d));Assert.Equal("player",g.DecisionPlayerId);Choose(g,"WILD:2");Assert.Equal(2800,a.CurrentPP);Assert.Equal("computer",g.DecisionPlayerId);Choose(g,"WILD:3");Assert.DoesNotContain(a,g.Player.Field);Assert.Contains(d,g.Computer.Field);Assert.Equal(1800,d.CurrentPP);Assert.Equal(0,a.CombatPowerBonus);Assert.Equal(2,g.Player.AvailableEnergy);Assert.Equal(1,g.Computer.AvailableEnergy);Assert.False(g.IsWaiting);}
    [Fact] public void WildCanDefendButDoesNotBoostFaceDamage(){var g=Scene();var a=Unit(g.Player,"WCG-101",2000);var d=Unit(g.Computer,"WCG-203");Assert.True(g.Attack(g.Player,a,d));Choose(g,"WILD:1");Assert.Contains(d,g.Computer.Field);Assert.DoesNotContain(a,g.Player.Field);g=Scene();a=Unit(g.Player,"WCG-203");Assert.True(g.Attack(g.Player,a));Assert.False(g.IsWaiting);Assert.Equal(6,g.Computer.Hp);Assert.Equal(4,g.Player.AvailableEnergy);}
    [Theory][InlineData(1,true)][InlineData(2,false)]
    public void WildCannotOutpowerPoisonAndShieldUsesOnlyRemainingEnergy(int n,bool saves){var g=Scene(2);var a=Unit(g.Player,"WCG-203");a.Attachments.Add(new(new(cards.GetCard("WCG-062")!),g.Player.Id));var d=Unit(g.Computer,"WCG-051",1000);Assert.True(d.HasPoison);Assert.True(g.Attack(g.Player,a,d));Choose(g,"WILD:"+n);if(saves){Assert.Equal("SHIELD",g.CurrentPendingChoice!.Options[0].Id);Choose(g,"SHIELD");Assert.Contains(a,g.Player.Field);Assert.Equal(1800,a.CurrentPP);}else{Assert.False(g.IsWaiting);Assert.DoesNotContain(a,g.Player.Field);}Assert.Equal(0,g.Player.AvailableEnergy);}
    [Fact] public void ObservationRepeatsTopPairsSequentiallyBeforeResetAndNormalDraw(){var g=Scene(4);Unit(g.Computer,"WCG-202");Unit(g.Computer,"WCG-202");g.Computer.Deck.Clear();var top=new[]{"WCG-101","WCG-103","WCG-104","WCG-107","WCG-108","WCG-109"}.Select(id=>new CardInstance(cards.GetCard(id)!)).ToArray();g.Computer.Deck.AddRange(top);Assert.True(g.EndTurn());Assert.Equal("player",g.CurrentTurnPlayerId);Assert.Equal(TurnPhase.EndingTurn,g.CurrentPhase);Choose(g,"OBSERVE:2");Assert.Equal(0,g.Computer.AvailableEnergy);Assert.Equal(new[]{top[0].InstanceId.ToString(),top[1].InstanceId.ToString()},g.CurrentPendingChoice!.Options.Select(o=>o.Id));Choose(g,top[1].InstanceId.ToString());Assert.Equal(new[]{top[2].InstanceId.ToString(),top[3].InstanceId.ToString()},g.CurrentPendingChoice!.Options.Select(o=>o.Id));Choose(g,top[2].InstanceId.ToString());Assert.False(g.IsWaiting);Assert.Equal("computer",g.CurrentTurnPlayerId);Assert.Equal(4,g.Computer.AvailableEnergy);Assert.Equal(new[]{top[1],top[2],top[4]},g.Computer.Hand);Assert.Equal(new[]{top[5],top[0],top[3]},g.Computer.Deck);}
    [Theory][InlineData(0)][InlineData(1)] public void EmptyOrSingleCardObservationHandlesMandatoryDrawLoss(int deck){var g=Scene(2);Unit(g.Computer,"WCG-202");g.Computer.Deck.Clear();if(deck==1)g.Computer.Deck.Add(new(cards.GetCard("WCG-101")!));Assert.True(g.EndTurn());if(deck==1){Choose(g,"OBSERVE:1");Choose(g,g.CurrentPendingChoice!.Options[0].Id);Assert.Single(g.Computer.Hand);}Assert.True(g.IsOver);Assert.Equal("需要抽牌時牌庫已空",g.Computer.LossReason);}
    [Theory][InlineData("silenced")][InlineData("absent")][InlineData("no-energy")]
    public void ObservationNeedsLivingUnsilencedSourceAndEnergyAtWindow(string mode){var g=Scene(2);var m=Unit(g.Computer,"WCG-202");if(mode=="silenced")m.IsSilenced=true;if(mode=="absent")g.Computer.Field.Remove(m);if(mode=="no-energy")g.Computer.EnergyZone.ForEach(c=>c.IsTapped=true);Assert.True(g.EndTurn());Assert.False(g.IsWaiting);Assert.Equal("computer",g.CurrentTurnPlayerId);}
    [Fact] public void EndTurnDamageRemovesObserverBeforeObservationWindow(){var g=Scene();Unit(g.Player,"WCG-120");Unit(g.Computer,"WCG-202");Assert.True(g.EndTurn());Assert.True(g.SelectTarget(g.Computer.Field.Single()));Assert.DoesNotContain(g.Computer.Field,m=>m.HasObservation);Assert.False(g.IsWaiting);}
    [Theory][InlineData(true)][InlineData(false)] public void SoulReturnIsImmediateOptionalAndReturnsSameInstance(bool use){var g=Scene(2);var old=new CardInstance(cards.GetCard("WCG-204")!);g.Computer.Graveyard.Add(old);var m=Unit(g.Computer,"WCG-204");Assert.True(g.Attack(g.Player,Unit(g.Player,"WCG-101",2000),m));Assert.Equal(m.InstanceId,g.CurrentPendingChoice!.SourceInstanceId);Choose(g,use?"SOUL":"SKIP");Assert.Contains(old,g.Computer.Graveyard);Assert.Equal(use?0:2,g.Computer.AvailableEnergy);Assert.Equal(use,g.Computer.Hand.Any(c=>c.InstanceId==m.InstanceId));if(!use){Assert.True(g.EndTurn());Assert.False(g.IsWaiting);}}
    [Theory][InlineData("silenced")][InlineData("one-energy")][InlineData("bounce")][InlineData("discard")]
    public void SoulReturnNeverOffersDeferredOrNonDeathWindow(string mode){var g=Scene(mode=="one-energy"?1:2);var m=Unit(g.Computer,"WCG-204");if(mode=="silenced")m.IsSilenced=true;if(mode=="bounce")Invoke(g,"Bounce",m);else if(mode=="discard"){g.Computer.Field.Remove(m);g.Computer.Graveyard.Add(new(m.Card));}else Assert.True(g.Attack(g.Player,Unit(g.Player,"WCG-101",2000),m));Assert.False(g.IsWaiting);Assert.True(g.EndTurn());Assert.False(g.IsWaiting);}
    [Fact] public void SimultaneousDeathsEachNeedTheirOwnTwoEnergy(){var g=Scene(3);var a=Unit(g.Computer,"WCG-204");var b=Unit(g.Computer,"WCG-204");Invoke(g,"KillBatch",new[]{a,b},"犧牲",true);Choose(g,"SOUL");Assert.False(g.IsWaiting);Assert.Equal(1,g.Computer.AvailableEnergy);Assert.Single(g.Computer.Hand);Assert.Single(g.Computer.Graveyard);}
    [Fact] public void SacrificeReturnsCardButSummoningStillCostsThree(){var g=Scene(5);var m=Unit(g.Player,"WCG-204");Invoke(g,"KillBatch",new[]{m},"犧牲",true);Choose(g,"SOUL");var c=g.Player.Hand.Single();Assert.Equal(m.InstanceId,c.InstanceId);Assert.True(g.SummonMonster(g.Player,c));Choose(g,"SLOT:0");Assert.Equal(0,g.Player.AvailableEnergy);Assert.True(g.Player.Field.Single().IsTapped);}
    [Theory][InlineData(-1)][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]
    public void EveryAiCanResolveNewKeywordWindowsOnBothTurns(int level){var g=Scene(4);g.AiLevel=level;g.Computer.IsAi=true;var d=Unit(g.Computer,"WCG-203");Assert.True(g.Attack(g.Player,Unit(g.Player,"WCG-101",2000),d));Assert.True(g.ExecuteAiStep());Assert.Equal(3,g.Computer.AvailableEnergy);Assert.Contains(d,g.Computer.Field);g=Scene(2);g.AiLevel=level;g.Computer.IsAi=true;d=Unit(g.Computer,"WCG-204");Assert.True(g.Attack(g.Player,Unit(g.Player,"WCG-101",2000),d));Assert.True(g.ExecuteAiStep());Assert.Single(g.Computer.Hand);g=Scene(2);g.AiLevel=level;g.Computer.IsAi=true;Unit(g.Computer,"WCG-202");Assert.True(g.EndTurn());Assert.True(g.ExecuteAiStep());Assert.True(g.ExecuteAiStep());Assert.False(g.IsWaiting);Assert.Equal(2,g.Computer.Hand.Count);}
    [Fact] public void InvalidEnergyAmountCannotSpendAnything(){var g=Scene(2);Assert.True(g.Attack(g.Player,Unit(g.Player,"WCG-201")));Assert.False(g.SelectChoice(new(){Id="RAGE:3"}));Assert.Equal(2,g.Player.AvailableEnergy);Assert.Equal(7,g.Computer.Hp);}
    [Fact] public void ObservationAiLeavesLastCardForMandatoryDraw(){var g=Scene(4);g.Computer.IsAi=true;Unit(g.Computer,"WCG-202");g.Computer.Deck.Clear();g.Computer.Deck.Add(new(cards.GetCard("WCG-101")!));Assert.True(g.EndTurn());Assert.True(g.ExecuteAiStep());Assert.False(g.IsOver);Assert.False(g.IsWaiting);Assert.Single(g.Computer.Hand);}

}
